// === Tab: Sketch ===
const vertexShader = `
  precision mediump float;
  attribute vec3 aPosition;
  void main() {
    gl_Position = vec4(aPosition, 1.0);
  }
`;

let fragmentShader = `
	precision mediump float;

	uniform vec2 u_resolution;
	uniform vec2 u_mouse;
	uniform sampler2D tex;

	void main() {
			vec2 st = gl_FragCoord.xy / u_resolution;
			vec3 color = texture2D(tex, st * .001).rgb;
			color *= .9;
			color += length(st) * .01;
			gl_FragColor = vec4(vec3(color), 1.0);
	}
`;

const zoomFrag = `
    precision mediump float;

    uniform vec2 u_resolution;
    uniform sampler2D tex;
    const float sc = 6.;
    void main() {
        vec2 st = gl_FragCoord.xy / u_resolution;

        // pixelating
        //vec2 st = (floor(gl_FragCoord.xy / sc) * sc + sc / 2.) / u_resolution;

        vec2 centre = vec2((1. - (1. / sc)) / 2.);
	    vec2 tex_coord = st / sc + centre;

        float c = 0.0;
        for(float y = -0.5; y <= 0.5; y += 0.2){
            for(float x = -0.5; x <= 0.5; x += 0.2){
              c += texture2D(tex, tex_coord + vec2(x,y)/u_resolution).r; 
            }
        }
        c *= c;
        c /= 800.;

        gl_FragColor = vec4(vec3(c), 1.);
    }
`;

let canvas;
let myShader;
let pg, pg2;

function setup() {
  canvas = createCanvas(windowWidth - 100, windowHeight - 100);
  pixelDensity(1);
  noStroke();
  background(0)
  fill('red')
  ellipse(width / 2, height / 2, 1)

  pg = createGraphics(width, height, WEBGL)
  pg.pixelDensity(1)
  myShader = pg.createShader(vertexShader, fragmentShader)
  pg.shader(myShader)

  myShader.setUniform('tex', canvas)
  myShader.setUniform('u_resolution', [width, height])

  pg2 = createGraphics(width, height, WEBGL)
  pg2.pixelDensity(1)
  zoomShader = pg2.createShader(vertexShader, zoomFrag)

  //frameRate(1)
}

function draw() {
  pg.shader(myShader)
  pg.quad(-1, -1, -1, 1, 1, 1, 1, -1)
  myShader.setUniform('tex', pg)

  //zoomShader.setUniform('tex', pg)
  //zoomShader.setUniform('u_resolution', [width, height])
  //pg2.shader(zoomShader)
  //pg2.quad(-1, -1, -1, 1, 1, 1, 1, -1)

  image(pg, 0, 0)
  /*
  noFill()
