  */
}

let isPlaying = true;

function keyPressed() {
  isPlaying = !isPlaying
  if (isPlaying) loop()
  else noLoop()
}

function windowResized() {
  resizeCanvas(windowWidth - 100, windowHeight - 100)
  myShader.setUniform('u_resolution', [width, height])
}

